    if (kind !== 'object' && kind !== 'array') return value;
    if (depth >= limit) return kind === 'array' ? '[数组 ' + value.length + ' 项]' : '{对象 ' + keysOf(value).length + ' 键: ' + keysOf(value).slice(0, 12).join(', ') + '}';
