  var DISCOVER_SYSTEM = [
    '你是 Reader-II 语义适配的路径发现器。',
    '任务：在宿主角色卡的 MVU 变量结构里，按“语义”为下面七个槽位指认对应路径。宿主的变量名不必与 Reader 相同。',
    '只能引用输入里真实存在的路径与字段，绝不臆造；语义对不上的槽位给 null，宁可留空也不要硬凑。',
    '只输出一个 JSON 对象，不要解释，不要 Markdown 代码块。',
    '',
    '槽位语义：',
    '- location 当前地点：主角此刻所在的地点。指向一个字符串，或由若干地点文本组成的小对象。',
    '- currency 货币：主角持有的通用货币或点数，指向一个数值。不要选等级、经验、生命值、属性点。',
    '- characters 重要角色：以角色名为键的对象表，或每项含名字的数组；条目里要有好感度一类的数值（可给 favor 字段路径），可选在场 present、身份 identity。',
    '- tasks 任务：当前任务 / 委托清单（名字做键的对象表，或含名字字段的数组）。',
    '- skills 用户技能：主角自己的技能 / 能力清单。不要选某个同伴的技能，也不要选物品、装备、属性。',
    '- statuses 用户当前状态：主角身上的状态效果清单；条目里要有效果文本 effect 与持续时间 duration，可选来源 source。',
    '- inventory 背包：主角持有的物品清单（对象表、“名字: 数量”表或名字数组）；可给 count / quality / type / tags / effect / description 字段路径。',
    '',
    '输出格式（path 是从 stat_data 之后开始的路径段数组；字段路径是条目内的相对路径段数组，没有就省略）：',
    '{"location":{"path":["世界","地点"]},"currency":null,"characters":{"path":["关系列表"],"fields":{"favor":["好感度"],"present":["在场"],"identity":["身份"]}},"tasks":null,"skills":{"path":["主角","技能"]},"statuses":{"path":["主角","状态效果"],"fields":{"effect":["效果"],"duration":["剩余时间"],"source":["来源"]}},"inventory":{"path":["主角","背包"],"fields":{"count":["数量"],"description":["描述"]}}}'
  ].join('\n');

  function looseJson(text) {
    var source = String(text || '').replace(/```(?:json)?/gi, '').trim();
    var start = source.indexOf('{');
    var end = source.lastIndexOf('}');
    if (start < 0 || end <= start) return null;
    var body = source.slice(start, end + 1);
    try { return JSON.parse(body); } catch (error) { /* try a light repair */ }
    /* 用函数替换：主脚本里不能出现「$」加数字（酒馆助手嵌脚本时可能当成替换串，见 build.mjs 的 assertEmbeddable）。 */
    try { return JSON.parse(body.replace(/,\s*([}\]])/g, function (match, close) { return close; })); } catch (error) { return null; }
  }

  function hostRef(segs) { return 'hostref:' + encodeURIComponent(JSON.stringify(segs)); }

  function displayPath(input) {
    var segs = input;
    if (typeof input === 'string' && input.indexOf('hostref:') === 0) {
      try { segs = JSON.parse(decodeURIComponent(input.slice(8))); } catch (error) { return ''; }
    }
